query (
  $start: DateTime!,
  $end: DateTime!,
){
  oee(
    first:null
    where:{
			_and:[
        { creditedAt:{_gte: $start} },
        { creditedAt:{_lte: $end}}
      ]
  	}){
    total
    edges{
      node{
        id
        workOrderCode
        workOrderNumber
        shiftId
        productNoRevision
        workcenterId

        oee

        availability
        availabilityWeight
        totalTime
        productionTime
        plannedDowntime
        unplannedDowntime

        performance
        performanceWeight
        idealRate
        totalQuantity
        totalScrapQuantity
        totalProductionQuantity

        quality
        qualityWeight

        creditedAt
      }
    }
  }
}

data.transform:
(
  $groupByFields := function($oee, $keys){
    $groupBy(
      $oee,
      $pick(?,$keys)~>$values~>$join(?, "::")
    )
  };

  $isBetween := function($oee, $timeFrame){(
    $date := $moment($oee.creditedAt);
    $start := $moment($timeFrame.start);
    $end := $moment($timeFrame.end);

    ($date.isAfter($start) and $date.isBefore($end)) or
    ($date.isSame($start) or $date.isSame($end))
  )};

  $data := oee.edges.node;
  $map($state.context.configs, | $ | { "data": $filter($data, $isBetween(?, timeRange))~>$groupByFields(?,dimensions) } | )

)

(
  $calcOee := $mapValues(
    ?,
    function($oees){(

      $oees := $oees~>|$| 
        {
          "availabilityWeighted": availability * (availabilityWeight?availabilityWeight:0),
          "performanceWeighted": performance * productionTime,
          "qualityWeighted": quality * totalQuantity
        }
       |;       

      /*Calculate Availability*/
      $plannedProductionTime := $sum($oees.productionTime);
      $unplannedDownTime := $sum($oees.unplannedDowntime);

      $availabilityWeight := ($sum($oees.availabilityWeight.($?$))? $sum($oees.availabilityWeight.($?$)) : 0);
      $availability := $availabilityWeight=0? 0 : $sum($oees.availabilityWeighted) / $availabilityWeight;

      /*Calculate Performance*/
      $totalQuantity := $sum($oees.totalQuantity);
      $performanceWeight := $sum($oees.productionTime);
      $performance := $performanceWeight = 0 ? 0 : $sum($oees.performanceWeighted) / $performanceWeight ;


      /*Calculate Quality*/
      $goodTotal := $sum($oees.totalProductionQuantity);
      $qualityWeight := $sum($oees.totalQuantity);
      $quality := $qualityWeight=0? 0 : $sum($oees.qualityWeighted) / $qualityWeight;

      /*OEE Dimensions*/
      $shiftId := $first($oees.shiftId);
      $workcenterId := $first($oees.workcenterId);
      $creditedAt := $first($oees.creditedAt);


      $aggregateOee := {
        "productionTime": $plannedProductionTime,
        "unplannedDowntime": $unplannedDownTime,
        "availabilityWeight": $availabilityWeight,
        "availability": $availability,

        "totalQuantity": $totalQuantity,
        "performanceWeight": $performanceWeight,
        "performance": $performance,


        "totalProductionQuantity": $goodTotal,
        "qualityWeight": $qualityWeight,
        "quality": $quality,


        "oee": $availability * $performance * $quality 

      };

      $oees~>$first~>|$| $aggregateOee, ["creditedAt", "idealRate", "availabilityWeighted", "performanceWeighted", "qualityWeighted"]|
    )}
  );

 $map($, |$| {"data": $calcOee(data)} | )

)

