(
  $timeZone := setting.edges.node.defaultValue;
  $shifts := productionSetup.edges[0].node.workcenter.shiftGroup.shifts.edges.node;
  $offShift:={
    "id": "offShift",
    "name": "Off Shift",
    "endHour": 23,
    "endMinute": 59,
    "startHour": 0,
    "startMinute": 0,
    "active": true,
    "creditAtStart": true,
    "friday": true,
    "monday": true,
    "saturday": true,
    "sunday": true,
    "thursday": true,
    "tuesday": true,
    "wednesday": true,
