      $shiftStart := $shift.startHour + ($shift.startMinute / 60);
      $shiftEnd := $shift.endHour + ($shift.endMinute / 60);

      $hourStart := $hourStartDate.hour() + ($hourStartDate.minute() / 60);
      $hourEnd := $hourEndDate.hour() + ($hourEndDate.minute() / 60);

      $range := ((($hourEnd + 24) - $hourStart) % 24);

      $isShiftStartInHour := ((($shiftStart + 24) - $hourStart) % 24) ;
      $isShiftEndInHour := ((($shiftEnd + 24) - $hourStart) % 24) ;

      $start := $isShiftStartInHour< $range? 
