data.query:
query (
  $workcenterId: String!
  $modeId: String,
  $eventId: String
){

  setting(where:{
    id: {_eq: "TimeZone"}
  }) {
    edges {
      node {
        id
        defaultValue
      }
    }
  }

  productionSetup(where:{
    workcenterId:{_eq : $workcenterId}
  }) {
    edges {
      node {
        id
        mode{
          id
          modeTypeId
        }
        productionRunId
        productionSetupOutputs {
          edges {
            node {
              id
              operationNumber
              operationCode
              productNumber
              productRevision
              productNumberRevision
              workOrderNumber
            }
          }
        }
      }
    }
  }

  workcenter(
    where:{ id:{ _eq: $workcenterId} }
  ) {
    edges {
      node {
        id
        shiftGroup{
          shifts(
            where:{
              active:{_eq: true}
            }
          ){
            edges{
              node{
                 id
                  name
                  creditAtStart
                  monday
                  tuesday
                  wednesday
                  thursday
                  friday
                  saturday
                  sunday
                  startHour
                  startMinute
                  endHour
                  endMinute
              }
            }
          }
        }
        modeGroup{
          modeList(
            where:{
              modeId:{_eq: $modeId}
            }
            first: 1
          ){
            total
            edges{
              node{
                eventGroup{
                  defaultEvent: eventList(
                    where:{
                      default:{_eq: true}
                    }
                    first: 1
                  ) {
                    total
                    edges {
                      node {
                        id
                        eventId
                        requireNote
                      }
                    }
                  }
                  eventList  (
                    where:{
                      _and:[
                        {
                      		eventId:{
                            _eq: $eventId
                          }    
                        },
                        {
                      		_not:{
                            eventId:{
                              _eq: ""
                            } 
                          }
                        }
                      ]

                    }
        					){
                    total
                    edges{
                      node{
                        requireNote
                      }
                    }
                  }
                }
                mode{
                  modeTypeId

                }
              }
            }
          }
        }
        currentWorkcenterHistory{
          id
          modeId
          eventId
        }
      }
    }
  }
}

