data.query:
query (
  $startTime: DateTime!,
  $endTime: DateTime!,
  $workcenterId: String!
){
  workcenterHistory(
    where:{ 
      _or:[
        {
          _and:[
            { occurAt:{_gte: $startTime} }
            { occurAt:{_lt: $endTime} }
          ]
        },
        {
          _and:[
            { endAt:{_gte: $startTime} }
            { endAt:{_lt: $endTime} }
          ]
        },
        { _and: [ 
        	{endAt: { _isNull: true }}
          {occurAt: {_gte: $startTime}}
          {occurAt: {_lt: $endTime}}
      ]}
      ]
      workcenterId:{
        _eq: $workcenterId
      }
    }
    first: null
    orderBy: {
      field:occurAt, direction:asc
    }
	){
    total
    edges {
      node {
        occurAt
        endAt
        transactionTypeId
        workcenterId
        workcenter{
          code
        }
        mode {
          name        
          modeType {
            color
            production
            maintenance
            other
            disabled

            changeover
          }
        }
        event {
          name
          eventType {
            id
            color
            name
          }
        }
      }
    }
  }

  eventType{
    edges{
      node{ id name color }
    }
  }

    setting(
    where:{
      id:{_eq: "TimeZone"}
    }
  ){
    edges{
      node{
        defaultValue
      }
    }
  }
}

data.transform:
(
  $timezone := setting.edges.node.defaultValue;
  $fitModeToRange := function($startBound, $endBound, $mode){(

    $modeStart := $coalesce([ $mode.occurAt , $startBound])~>$moment(?) ;
    $modeEnd := $coalesce([ $mode.endAt, $endBound])~>$moment(?);

    $endBoundObj := $moment($endBound);
    $startBoundObj := $moment($startBound);

    $start := $modeStart.isAfter($startBound)? $modeStart : $startBoundObj;
    $end := $modeEnd.isBefore($endBound)? $modeEnd : $endBoundObj;

    $isNilOrEmpty($mode.occurAt) and $isNilOrEmpty($mode.endAt)? 
      $throw("Mode has no occurAt or endAt", $mode) :
      $merge([
        $mode,
        {"occurAt": $start.format(), "endAt": $end.format(), "originalTimes":{"occurAt": $modeStart, "endAt": $endAt}}
      ])

  )};
  $durationOrNow := function($v){(
    $end := $moment();
    $mode := $fitModeToRange($$.startAt, $end.format(), $v);

    $start := $moment($mode.occurAt);

    $durationTillNow := $end.diff($start, "seconds");

    $coalesce([$mode.duration, $durationTillNow])

  )};

  $history := [ workcenterHistory.edges.node.($fitModeToRange($state.context.REQUEST.start, $state.context.REQUEST.end, $)) ];

  $legend := {
    "item": eventType.edges.node.{
      "label": name,
      "color": color
    }
  };

  $task := {
    "task": [$history#$i.{
        "label": $coalesce([ event.name, "No Event"]),
        "processid": "1",
        "start": $moment( occurAt ).tz($timezone).format("HH:mm:ss"),
        "end": $moment( endAt ).tz($timezone).format("HH:mm:ss"),
        "bordercolor": "#62B58D",
        "color": $coalesce([ event.eventType.color, "#ffffff"]),
        "id": $i + 1
      }]

  };

  $processes := {
    "isbold": "1",
    "headertext": "Workcenter",
    "process": [
      {
        "label": workcenterHistory.edges[0].node.workcenter.code,
        "id": "1"
      }
    ]
  };

  $categories := [
    {
      "category": [
        {
          "start": $moment($state.context.REQUEST.start).tz($timezone).format("HH:mm:ss"),
          "end": $moment($state.context.REQUEST.end).tz($timezone).format("HH:mm:ss"),
          "name": "Shift"
        }
      ]
    }
  ];

  {
    "chart": {
      "caption": "Machine Operating Schedule",
      "theme": "candy",
      "dateformat": "yyyy-mm-dd",
      "plottooltext": "Status for period <b>$start - $end</b> is <b>$label</b>",
      "outputdateformat": "hh12:mn ampm",
      "borderColor": "#424242"
    },
    "legend": $legend,
    "tasks": $task,
    "processes": $processes,
    "categories": $categories
  }
)

